param([string]$RunDate='PLAN-DATE',[ValidateSet('PLAN','EXECUTE')][string]$ExecutionMode='PLAN')
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$result=Join-Path $root 'backend\experiments\results\experiment-1-29';New-Item -ItemType Directory -Force (Join-Path $result 'plan')|Out-Null;$runner=Join-Path $PSScriptRoot 'run-experiment-1-29-core.ps1'
$runs=@('BASELINE-001','REMEDIATION-001','BASELINE-002','REMEDIATION-002','BASELINE-003','REMEDIATION-003')
if($ExecutionMode-eq'PLAN'){$manifests=@();foreach($arm in $runs){$parts=$arm.Split('-');& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $runner -Condition $parts[0] -RunIndex $parts[1] -RunDate $RunDate -ExecutionMode PLAN;if($LASTEXITCODE){throw "PLAN_CORE_FAILED: $arm"};$p=Join-Path $result "plan\$($parts[0])-$($parts[1])-command-manifest.json";if(-not(Test-Path $p)){throw "PLAN_MANIFEST_MISSING: $arm"};$m=Get-Content $p -Raw|ConvertFrom-Json;if($m.experiment-ne'Experiment 1-29'-or$m.runId-ne"RUN-$RunDate-EXP129-$arm"-or$m.executionMode-ne'PLAN'-or$m.composeFiles.Count-ne7){throw "PLAN_MANIFEST_INVALID: $arm"};$manifests+=$p};$ledger=[ordered]@{experiment='Experiment 1-29';runDate=$RunDate;executionMode='PLAN';requestedRuns=$runs;manifests=$manifests;startedRuns=0;completedRuns=0;failedRuns=0;warmupInvocations=0;coreInvocations=0;k6Invocations=0;executionStatus='NOT_RUN';policyDecision='NOT_RUN'};$ledger|ConvertTo-Json -Depth 10|Set-Content (Join-Path $result 'plan/runner-readiness.json') -Encoding UTF8;Write-Output 'EXP129_PLAN_READY';exit 0}
$states=@();$failure=$null;foreach($arm in $runs){$parts=$arm.Split('-');try{& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $runner -Condition $parts[0] -RunIndex $parts[1] -RunDate $RunDate -ExecutionMode EXECUTE;if($LASTEXITCODE){throw "core exit $LASTEXITCODE"}}catch{$failure=$_;break}}
foreach($arm in $runs){$id="RUN-$RunDate-EXP129-$arm";$dir=Join-Path $result "core\$id";$warm=Join-Path $root "experiment\results\SMOKE-$RunDate-EXP129-$arm";$core=Join-Path $root "experiment\results\$id";$states+=[ordered]@{runId=$id;started=Test-Path $dir;warmupInvoked=Test-Path $warm;coreInvoked=Test-Path $core;k6Invoked=Test-Path $core;completed=Test-Path (Join-Path $dir 'COMPLETED');failed=Test-Path (Join-Path $dir 'EXECUTION_FAILED')}}
$ledger=[ordered]@{experiment='Experiment 1-29';runDate=$RunDate;executionMode='EXECUTE';requestedRuns=$runs;startedRuns=@($states|Where-Object started).Count;completedRuns=@($states|Where-Object completed).Count;failedRuns=@($states|Where-Object failed).Count;notStartedRuns=@($states|Where-Object{-not$_.started}|ForEach-Object runId);warmupInvocations=@($states|Where-Object warmupInvoked).Count;coreInvocations=@($states|Where-Object coreInvoked).Count;k6Invocations=@($states|Where-Object k6Invoked).Count;executionStatus=if($failure){'FAILED'}elseif(@($states|Where-Object completed).Count-eq6){'COMPLETED'}else{'INCOMPLETE'};policyDecision='NOT_RUN';runStates=$states};$ledger|ConvertTo-Json -Depth 12|Set-Content (Join-Path $result 'plan/runner-readiness.json') -Encoding UTF8;if($failure){throw $failure}

